-- GERADO por `python -m zelo.gerar_sql` a partir de data/tabela_triagem.csv. NAO edite a mao.
-- Para mudar uma regra: edite o CSV, rode o gerador e `python triagem_zelo.py --seed`.

CREATE TABLE IF NOT EXISTS regras_triagem (
    codigo VARCHAR(10) PRIMARY KEY,
    tipo_ocorrencia VARCHAR(200) NOT NULL,
    categoria VARCHAR(50) NOT NULL CHECK (categoria IN ('Elétrica', 'Hidráulica', 'Umidade', 'Cobertura', 'Estrutura', 'Gás', 'Elevador', 'Incêndio', 'Lazer', 'Áreas verdes', 'Acesso', 'Segurança', 'Convivência', 'Limpeza', 'Mobiliário', 'Gestão', 'Não é ocorrência')),
    urgencia_base VARCHAR(10) CHECK (urgencia_base IN ('Baixa', 'Média', 'Alta')),
    o_que_sobe_ou_desce TEXT NOT NULL,
    modificadores TEXT NOT NULL DEFAULT '',
    quem_resolve VARCHAR(100) NOT NULL,
    sensivel BOOLEAN NOT NULL,
    sistema_garantia VARCHAR(40),
    origem VARCHAR(40) NOT NULL DEFAULT 'tabela_v3',
    versao VARCHAR(10) NOT NULL DEFAULT 'v3'
);

ON CONFLICT (codigo) DO UPDATE SET tipo_ocorrencia = EXCLUDED.tipo_ocorrencia, categoria = EXCLUDED.categoria, urgencia_base = EXCLUDED.urgencia_base, o_que_sobe_ou_desce = EXCLUDED.o_que_sobe_ou_desce, modificadores = EXCLUDED.modificadores, quem_resolve = EXCLUDED.quem_resolve, sensivel = EXCLUDED.sensivel, sistema_garantia = EXCLUDED.sistema_garantia, origem = EXCLUDED.origem;
